makeMtLab(document.getElementById("lab-l68"),{id:"l68",scenarios:[{"label": "Ví dụ: Ví dụ chuẩn", "note": "Ca 8 h.", "steps": [{"t": "A", "html": "<p class=\"mt-calc\">23 400 / 27 000 = 0,8667<\/p>"}, {"t": "P", "html": "<p class=\"mt-calc\">2 × 10 500 / 23 400 = 0,8974<\/p>"}, {"t": "Q", "html": "<p class=\"mt-calc\">10 200 / 10 500 = 0,9714<\/p>"}, {"t": "OEE", "html": "<p class=\"mt-calc\">2 × 10 200 / 27 000 = 0,7556<\/p>", "ask": {"q": "A × P × Q có bằng 0,7556 không?", "o": ["Có", "Không"], "a": 0}}]}, {"label": "Ví dụ: Dữ liệu FX5U giả lập", "note": "830 s, không nghỉ.", "steps": [{"t": "Thời gian", "html": "<p class=\"mt-calc\">Chạy 725 s, dừng 45 s, chờ 60 s<\/p>"}, {"t": "Số đếm", "html": "<p class=\"mt-calc\">348 tốt, 14 lỗi<\/p>"}, {"t": "OEE", "html": "<p class=\"mt-calc\">2 × 348 / 830 = 0,8386<\/p>"}]}, {"label": "Ví dụ: Máy không chạy", "note": "run_s = 0.", "steps": [{"t": "P", "html": "<p class=\"mt-calc\">total / nullif(0, 0) = NULL<\/p>"}, {"t": "Dashboard", "html": "<p class=\"mt-calc\">Hiện —, không báo lỗi chia 0<\/p>"}]}, {"label": "Lỗi: Làm tròn trước", "note": "Hiển thị 87 %, 90 %, 97 %.", "steps": [{"t": "Nhân số đã làm tròn", "html": "<p class=\"mt-calc\">75,95 %<\/p>"}, {"t": "Đúng", "html": "<p class=\"mt-calc\">75,56 %: làm tròn chỉ khi hiển thị<\/p>"}]}, {"label": "Bẫy: P = 112 %", "note": "Chu kỳ lý tưởng 2,2 s, máy chạy 2,0 s.", "steps": [{"t": "P > 1", "html": "<p class=\"mt-calc\">Chu kỳ lý tưởng chậm hơn khả năng thật<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Đặt lại chu kỳ lý tưởng của sản phẩm<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l68"),"l68",[{"kind": "num", "t": "Tính OEE", "d": "<p>Trả lời bằng % (2 chữ số thập phân).<\/p>", "items": [{"q": "Chu kỳ 1,5 s, 15 000 tốt, kế hoạch 27 000 s. OEE?", "a": 83.33, "unit": "%", "tol": 0.01}, {"q": "Chạy 24 300 s, kế hoạch 27 000 s. A?", "a": 90, "unit": "%", "tol": 0.01}, {"q": "Chu kỳ 2 s, tổng 11 000, chạy 24 000 s. P?", "a": 91.67, "unit": "%", "tol": 0.01}, {"q": "Tốt 9 800, tổng 10 000. Q?", "a": 98, "unit": "%", "tol": 0.01}], "hints": ["OEE = chu kỳ × tốt / kế hoạch.", "P = chu kỳ × tổng / chạy."], "why": "83,33; 90; 91,67; 98."}, {"kind": "pick", "t": "Đúng hay sai?", "d": "<p>Theo bài.<\/p>", "cats": ["Đúng", "Sai"], "items": [{"q": "OEE = A × P × Q", "a": 0}, {"q": "Làm tròn A, P, Q trước khi nhân", "a": 1}, {"q": "P > 100 % thì cắt về 100 %", "a": 1}, {"q": "Dùng nullif để tránh chia 0", "a": 0}], "hints": ["Làm tròn ở hiển thị.", "P > 100 % là cấu hình sai."], "why": "A×P×Q, nullif: đúng; làm tròn trước, cắt P: sai."}, {"kind": "order", "t": "Truy vấn OEE", "d": "<p>Sắp xếp các CTE.<\/p>", "items": ["planned: ca trừ nghỉ", "dur: thời gian theo trạng thái", "cnt: số tốt, tổng, chu kỳ lý tưởng", "t: ghép planned_s, run_s, cnt", "SELECT A, P, Q, OEE"], "hints": ["Thời gian trước, số đếm sau.", "Tính chỉ số ở cuối."], "why": "planned → dur → cnt → t → SELECT."}]);
mesSim(document.getElementById("sim-l68"),Object.assign({id:"l68"},{kind:"db",title:"A, P, Q, OEE bằng SQL trên ví dụ chuẩn",sub:"Ca C1 của L1-M1: sự kiện như Bài 13, 10 500 hộp, 10 200 đạt, chu kỳ lý tưởng 2,0 s.",show:"state_event",rows:12,
 tables:[{name:"shift",cols:[{n:"shift_id",ty:"text",pk:1},{n:"start_ts",ty:"timestamptz"},{n:"end_ts",ty:"timestamptz"},{n:"break_start",ty:"timestamptz"},{n:"break_end",ty:"timestamptz"}],
  rows:[{shift_id:"C1",start_ts:"2026-11-12 06:00",end_ts:"2026-11-12 14:00",break_start:"2026-11-12 10:00",break_end:"2026-11-12 10:30"},{shift_id:"C2",start_ts:"2026-11-12 14:00",end_ts:"2026-11-12 22:00",break_start:"2026-11-12 18:00",break_end:"2026-11-12 18:30"}]},{name:"state_event",cols:[{n:"machine_id",ty:"text",nn:1},{n:"state",ty:"text",nn:1,check:"state in ('RUNNING','IDLE','DOWN','NO_DATA')"},{n:"start_ts",ty:"timestamptz",nn:1},{n:"end_ts",ty:"timestamptz"},{n:"fault_code",ty:"int"},{n:"reason_id",ty:"text"}],
  exclude:{key:"machine_id",start:"start_ts",end:"end_ts",name:"no_overlap"},
  rows:[{machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 06:00",end_ts:"2026-11-12 09:00"},{machine_id:"L1-M1",state:"DOWN",start_ts:"2026-11-12 09:00",end_ts:"2026-11-12 09:40",fault_code:12},
   {machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 09:40",end_ts:"2026-11-12 12:30"},{machine_id:"L1-M1",state:"IDLE",start_ts:"2026-11-12 12:30",end_ts:"2026-11-12 12:50"},{machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 12:50",end_ts:"2026-11-12 14:00"}]},{name:"product",cols:[{n:"product_id",ty:"text",pk:1},{n:"ideal_cycle_s",ty:"numeric"}],rows:[{product_id:"SP-07",ideal_cycle_s:2.0}]},
  {name:"count_delta",cols:[{n:"machine_id",ty:"text"},{n:"ts",ty:"timestamptz"},{n:"good",ty:"int"},{n:"reject",ty:"int"}],rows:[{machine_id:"L1-M1",ts:"2026-11-12 09:00",good:5200,reject:150},{machine_id:"L1-M1",ts:"2026-11-12 14:00",good:5000,reject:150}]}],
 sql:"WITH planned AS (\n  SELECT extract(epoch FROM (end_ts - start_ts - (break_end - break_start))) AS planned_s, s.*\n  FROM shift s WHERE shift_id = 'C1'),\nrun AS (\n  SELECT sum(extract(epoch FROM (least(e.end_ts, p.end_ts) - greatest(e.start_ts, p.start_ts)))\n     - greatest(0, extract(epoch FROM (least(e.end_ts, p.break_end) - greatest(e.start_ts, p.break_start))))) AS run_s\n  FROM state_event e, planned p\n  WHERE e.state = 'RUNNING' AND e.start_ts < p.end_ts AND e.end_ts > p.start_ts),\ncnt AS (SELECT sum(good) AS good, sum(good + reject) AS total FROM count_delta)\nSELECT p.planned_s, r.run_s, c.good, c.total,\n  r.run_s / p.planned_s AS a,\n  2.0 * c.total / r.run_s AS p,\n  c.good * 1.0 / c.total AS q,\n  2.0 * c.good / p.planned_s AS oee\nFROM planned p, run r, cnt c;",
 tasks:[{t:"Chạy truy vấn: kế hoạch, chạy, đạt, tổng và bốn chỉ số.",ok:"27 000 s, 23 400 s, 10 200 / 10 500; A 0,8667 · P 0,8974 · Q 0,9714 · OEE 0,7556.",check:(s,c)=>c.has("sql",e=>e.ok&&e.rows.length===1&&Math.abs(e.rows[0][7]-0.7556)<0.0001)},
  {t:"Bẫy làm tròn: viết SELECT round(0.87 * 0.90 * 0.97, 4) và so với 0,7556.",ok:"0,7595: làm tròn từng thành phần rồi nhân lệch 0,39 điểm %. Chỉ làm tròn kết quả hiển thị.",check:(s,c)=>c.has("sql",e=>e.ok&&e.rows.length===1&&Math.abs(e.rows[0][0]-0.7595)<0.0001)},
  {t:"Bẫy số nguyên: SELECT 10200 / 10500 cho ra bao nhiêu?",ok:"0: PostgreSQL chia hai số nguyên thì bỏ phần lẻ. Nhân 1.0 hoặc ép ::numeric trước khi chia.",check:(s,c)=>c.has("sql",e=>e.ok&&/10200\s*\/\s*10500/.test(e.sql)&&e.rows[0]&&e.rows[0][0]===0)}]}));

